public ListNode? MergeKListsSequential(ListNode[] lists)
{
    ListNode? result = null;

    foreach (var list in lists)
    {
        result = MergeTwo(result, list);
    }

    return result;
}

private static ListNode? MergeTwo(ListNode? a, ListNode? b)
{
    var dummy = new ListNode(0);
    var tail = dummy;

    while (a != null && b != null)
    {
        if (a.val <= b.val) { tail.next = a; a = a.next; }
        else { tail.next = b; b = b.next; }
        tail = tail.next;
    }

    tail.next = a ?? b;
    return dummy.next;
}

public ListNode? MergeKLists(ListNode[] lists)
{
    var heap = new PriorityQueue<ListNode, int>();

    // Seed with the head of every list
    foreach (var list in lists)
    {
        if (list != null)
        {
            heap.Enqueue(list, list.val);
        }
    }

    var dummy = new ListNode(0);
    var tail = dummy;

    while (heap.Count > 0)
    {
        var node = heap.Dequeue();
        tail.next = node;
        tail = node;

        if (node.next != null)
        {
            heap.Enqueue(node.next, node.next.val);
        }
    }

    tail.next = null;
    return dummy.next;
}

public ListNode? MergeKListsDivide(ListNode[] lists)
{
    if (lists.Length == 0) return null;

    int interval = 1;

    while (interval < lists.Length)
    {
        for (int i = 0; i + interval < lists.Length; i += interval * 2)
        {
            lists[i] = MergeTwo(lists[i], lists[i + interval]);
        }
        interval *= 2;
    }

    return lists[0];
}

public ListNode? MergeKLists(ListNode[] lists)
{
    var heap = new PriorityQueue<ListNode, int>();

    foreach (var list in lists)
        if (list != null) heap.Enqueue(list, list.val);

    var dummy = new ListNode(0);
    var tail = dummy;

    while (heap.Count > 0)
    {
        var node = heap.Dequeue();
        tail.next = node;
        tail = node;
        if (node.next != null) heap.Enqueue(node.next, node.next.val);
    }

    tail.next = null;
    return dummy.next;
}
